<?php
namespace App\Controllers; use App\Models\VerificationAssistanceRequestModel; use App\Services\AssistanceDocumentStorage; use CodeIgniter\RESTful\ResourceController; use Config\Database; use DomainException; use Throwable;
final class VerificationAssistanceApiController extends ResourceController { protected $format='json'; public function create(){ $key=config('VerificationAssistance')->apiKey;if($key===''||!hash_equals($key,$this->request->getHeaderLine('X-Verification-Assistance-Key')))return $this->failUnauthorized('Unauthorized request.');$throttle=service('throttler');if(!$throttle->check('assistance_api_'.hash('sha256',$this->request->getIPAddress()),20,3600))return $this->failTooManyRequests('Too many requests.');try{$data=$this->input();$upload=$this->request->getFile('supporting_document');if(!$upload)throw new DomainException('Supporting document is required.');$db=Database::connect();$lock='assistance:'.hash('sha256',$data['student_id'].'|'.$data['contact_email']);if((int)($db->query('SELECT GET_LOCK(?, 5) AS locked',[$lock])->getRowArray()['locked']??0)!==1)throw new \RuntimeException('Request service busy.');try{$model=new VerificationAssistanceRequestModel();if($model->where('student_id',$data['student_id'])->where('contact_email',$data['contact_email'])->whereIn('status',['pending','under_review'])->first())throw new DomainException('An active assistance request already exists.');$stored=(new AssistanceDocumentStorage())->store($upload);$id=$model->insert($data+$stored+['status'=>'pending']);if(!$id)throw new \RuntimeException('Request could not be saved.');$db->table('verification_assistance_audit_logs')->insert(['request_id'=>$id,'admin_id'=>null,'action'=>'submitted','notes'=>null,'created_at'=>gmdate('Y-m-d H:i:s')]);}finally{$db->query('SELECT RELEASE_LOCK(?)',[$lock]);}return $this->respondCreated(['received'=>true]);}catch(DomainException $e){return $this->failValidationErrors($e->getMessage());}catch(Throwable $e){log_message('error','Assistance request processing failed ({exceptionClass}).',['exceptionClass'=>$e::class]);return $this->failServerError('Assistance request could not be received.');}} private function input():array{$p=$this->request->getPost();$v=static fn($k,$m)=>is_string($p[$k]??null)?trim(mb_substr($p[$k],0,$m)):'';$d=['student_id'=>$v('student_id',30),'full_name'=>$v('full_name',150),'contact_email'=>strtolower($v('contact_email',150)),'program'=>$v('program',150),'explanation'=>$v('explanation',2000)];if(preg_match('/\A[A-Za-z0-9-]{1,30}\z/',$d['student_id'])!==1||$d['full_name']===''||filter_var($d['contact_email'],FILTER_VALIDATE_EMAIL)===false||$d['program']===''||$d['explanation']==='')throw new DomainException('Request fields are invalid.');return $d;}}
